	protected MRPRun read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created MRPRun" );

		MRPRun entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read MRPRun with primary key" );
		msg.append( mRPRunId );
		
		MRPRunFetchOneSummary fetchOneSummary = new MRPRunFetchOneSummary( mRPRunId );

		try {
			entity = MRPRunService.getMRPRunInstance().getMRPRun( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found MRPRun " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a MRPRun.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a MRPRun." );

		StringBuilder msg = new StringBuilder( "Failed to update a MRPRun : " );        
		MRPRun entity = read();
		UpdateMRPRunCommand command = generateUpdateCommand();
		command.setMRPRunId(entity.getMRPRunId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created MRPRun." );

			// for use later on...
			mRPRunId = entity.getMRPRunId();

			MRPRunService proxy = MRPRunService.getMRPRunInstance();  

			proxy.updateMRPRun( command ).get();

			LOGGER.info( "-- Successfully saved MRPRun - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + mRPRunId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a MRPRun.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created MRPRun." );

		MRPRun entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read MRPRun with id " + mRPRunId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read MRPRun with id " + mRPRunId );

			throw e;
		}

		try{
			MRPRunService.getMRPRunInstance().delete( new DeleteMRPRunCommand( entity.getMRPRunId() ) ).get();
			LOGGER.info( "-- Successfully deleted MRPRun with id " + mRPRunId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete MRPRun with id " + mRPRunId );

			throw e;
		}
	}

	/**
	 * get all MRPRuns.
	 */
	protected List<MRPRun> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of MRPRuns:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all MRPRun : " );        
		List<MRPRun> collection  = new ArrayList<>();

		try {
			// call the static get method on the MRPRunService
			collection = MRPRunService.getMRPRunInstance().getAllMRPRun();
			assertNotNull( collection, "An Empty collection of MRPRun was incorrectly returned.");
			
			// Now print out the values
			MRPRun entity = null;            
			Iterator<MRPRun> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getMRPRunId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

